"""Owner-confirmed B1 orchestration only; reuses exact ea31 artifact CLI.
No new installer, no production services, no background installation.
"""
import base64, fcntl, hashlib, io, json, os, re, stat, subprocess, sys, tarfile, time, zipfile, zlib
from pathlib import Path

HOST = 'iZd7oeikknn1z21sq6ji6zZ'
IMAGE = 'sha256:5341f193a5741b64f2acc63a99dc95910289fcc39ff17dacff373a50e233724d'
BASE = Path('/var/lib/xuanjun-p2-isolated-test')
ROOT = BASE / 'artifacts'
INPUT = BASE / 'b1-input-20261020'
LOGS = BASE / 'logs/b1-first-install-20261020'
TOOL_COMMIT = 'ea31dbbec2a8710b964efb38fa2975684bbd9739'
ZIP_SHA = '351e745e8dbadea6d3fd5f3e0ff10a678f9e4605f1428410f0a2d45117487955'
TAR_SHA = '3ac2cfde7340195f52fc9f1518a1929c130f7fa9fae925735334e17f56905a82'
MANIFEST_SHA = '591855b35c820c486ae07bbb91e681b983a3a2310feaedb57ae7c87fc9b66592'
REQUEST_SHA = '21ec24e119516493577dc5a4019ba913f076306565171a1d3ebbaa9e9efb659b'
ARCHIVE = 'xuanjun-p2-b1-release-20261020.tar'
PAYLOAD = ''


def sha(raw):
    return hashlib.sha256(raw).hexdigest()


def require(condition, reason):
    if not condition:
        raise RuntimeError(reason)


def validate_payload():
    payload = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    rawzip = base64.b64decode(payload['zip'])
    require(sha(rawzip) == ZIP_SHA, 'ZIP_DIGEST_MISMATCH')
    allowed = {ARCHIVE, 'MANIFEST.json', 'PACKAGE_INFO.json', 'SHA256SUMS',
               'execute-request.json', 'inspect-request.json', 'recover-request.json'}
    with zipfile.ZipFile(io.BytesIO(rawzip)) as archive:
        require(len(archive.infolist()) == len(allowed) and set(archive.namelist()) == allowed,
                'ZIP_MEMBER_MISMATCH')
        require(all(not i.is_dir() and i.file_size <= 1048576 for i in archive.infolist()), 'ZIP_SIZE_OR_TYPE')
        files = {name: archive.read(name) for name in sorted(allowed)}
    require(sha(files[ARCHIVE]) == TAR_SHA and len(files[ARCHIVE]) == 71680, 'TAR_DIGEST_MISMATCH')
    require(sha(files['MANIFEST.json']) == MANIFEST_SHA, 'MANIFEST_DIGEST_MISMATCH')
    request_raw = files['execute-request.json']
    require(sha(request_raw) == REQUEST_SHA and request_raw == files['inspect-request.json'] == files['recover-request.json'],
            'REQUEST_BYTES_MISMATCH')
    request = json.loads(request_raw)
    require(request['scope'] == 'ISOLATED_TEST_ONLY' and request['root'] == str(ROOT)
            and request['installation_id'] == 'p2-uk-isolated-20261020'
            and request['batch_id'] == 'b1-release' and request['attempt_id'] == 'b1-release-a1'
            and request['inputs']['archive'] == '/input/' + ARCHIVE
            and request['inputs']['archive_sha256'] == TAR_SHA, 'REQUEST_IDENTITY_MISMATCH')
    manifest = json.loads(files['MANIFEST.json'])
    require(manifest['installer_source_commit'] == TOOL_COMMIT, 'INSTALLER_BINDING_MISMATCH')
    expected = request['inputs']['files']
    with tarfile.open(fileobj=io.BytesIO(files[ARCHIVE]), mode='r:') as archive:
        members = archive.getmembers()
        require(len(members) == 4 and {m.name for m in members} == set(expected), 'TAR_MEMBER_MISMATCH')
        for member in members:
            require(member.isfile() and member.mode == 0o600, 'TAR_MEMBER_TYPE_OR_MODE')
            require(sha(archive.extractfile(member).read()) == expected[member.name], 'TAR_MEMBER_DIGEST')
    tools = {}
    for name, entry in payload['tools'].items():
        raw = base64.b64decode(entry['bytes'])
        require(sha(raw) == entry['sha256'], 'TOOL_DIGEST_MISMATCH')
        require(name.startswith('production/p2_artifacts/') and '/' not in name[len('production/p2_artifacts/'):], 'TOOL_PATH')
        tools[name] = raw
    require(set(tools) == {'production/p2_artifacts/' + n for n in ('__init__.py','__main__.py','installer.py')}, 'TOOL_SET')
    return rawzip, files, tools, request


def directory(path, uid, gid, mode):
    path.mkdir(mode=0o700)
    fd = os.open(str(path), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fchown(fd, uid, gid)
        os.fchmod(fd, mode)
        os.fsync(fd)
    finally:
        os.close(fd)
    sync(path.parent)


def sync(path):
    fd = os.open(str(path), os.O_RDONLY | os.O_DIRECTORY | os.O_NOFOLLOW)
    try:
        os.fsync(fd)
    finally:
        os.close(fd)


def write(path, raw, uid=0, gid=0, mode=0o600):
    fd = os.open(str(path), os.O_WRONLY | os.O_CREAT | os.O_EXCL | os.O_NOFOLLOW, mode)
    with os.fdopen(fd, 'wb') as out:
        out.write(raw)
        os.fchown(out.fileno(), uid, gid)
        os.fchmod(out.fileno(), mode)
        out.flush()
        os.fsync(out.fileno())
    sync(path.parent)


def read_file(path):
    fd = os.open(str(path), os.O_RDONLY | os.O_NOFOLLOW | os.O_NONBLOCK)
    with os.fdopen(fd, 'rb') as source:
        info = os.fstat(source.fileno())
        require(stat.S_ISREG(info.st_mode), 'NON_REGULAR_EVIDENCE')
        raw = source.read()
    return raw, info


def installed(request):
    key = request['installation_id'] + '--' + request['batch_id']
    dest = ROOT / 'versions' / key
    expected = request['inputs']['files']
    found = set()
    for parent, dirs, names in os.walk(str(dest), followlinks=False):
        for name in dirs:
            require(stat.S_ISDIR(os.lstat(os.path.join(parent, name)).st_mode), 'INSTALLED_UNSAFE_DIRECTORY')
        for name in names:
            found.add(str(Path(parent, name).relative_to(dest)))
    require(found == set(expected), 'INSTALLED_FILE_SET')
    rows = {}
    for name, expected_sha in sorted(expected.items()):
        path = dest / name
        raw, info = read_file(path)
        mode = stat.S_IMODE(info.st_mode)
        require(sha(raw) == expected_sha and mode == request['inputs']['modes'][name]
                and (info.st_uid, info.st_gid) == (1002, 1002), 'INSTALLED_SHA_MODE_OWNER:' + name)
        rows[name] = {'sha256': sha(raw), 'mode': mode, 'uid': info.st_uid, 'gid': info.st_gid,
                      'size': info.st_size, 'inode': info.st_ino, 'mtime_ns': info.st_mtime_ns}
    receipt_path = ROOT / '.p2_artifacts/receipts' / (key + '.json')
    raw, info = read_file(receipt_path)
    return {'files': rows, 'receipt': {'path': str(receipt_path), 'sha256': sha(raw),
                                     'inode': info.st_ino, 'mtime_ns': info.st_mtime_ns}}, raw


def command(action):
    return ['/bin/docker', 'run', '--interactive', '--pull=never', '--name=p2-uk-b1-' + action + '-20261020',
            '--cidfile=' + str(LOGS / (action + '.cid')),
            '--hostname=' + HOST, '--user=1002:1002', '--network=none', '--cap-drop=ALL',
            '--security-opt=no-new-privileges', '--read-only', '--pids-limit=96',
            '--memory=512m', '--memory-swap=1g', '--log-driver=none',
            '--mount=type=bind,src=' + str(INPUT) + ',dst=/input,readonly',
            '--mount=type=bind,src=' + str(ROOT) + ',dst=' + str(ROOT),
            '--workdir=/input/tools', '--env=PYTHONPATH=/input/tools',
            '--env=PYTHONNOUSERSITE=1', '--entrypoint=/usr/bin/python3.11',
            IMAGE, '-B', '-S', '-m', 'production.p2_artifacts', action]


def container_state(name):
    fields = '{"state":{{json .State}},"image":{{json .Image}},"user":{{json .Config.User}},"mounts":{{json .Mounts}},"network":{{json .HostConfig.NetworkMode}},"readonly":{{json .HostConfig.ReadonlyRootfs}},"cap_drop":{{json .HostConfig.CapDrop}},"security_opt":{{json .HostConfig.SecurityOpt}},"memory":{{json .HostConfig.Memory}},"memory_swap":{{json .HostConfig.MemorySwap}},"pids":{{json .HostConfig.PidsLimit}},"cpu_quota":{{json .HostConfig.CpuQuota}},"nano_cpus":{{json .HostConfig.NanoCpus}}}'
    p = subprocess.run(['/bin/docker', 'inspect', '--format', fields, name], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
    require(p.returncode == 0, 'CONTAINER_INSPECT_FAILED:' + name)
    return json.loads(p.stdout.decode())


def main():
    os.umask(0o077)
    require(os.geteuid() == 0 and os.uname().nodename.split('.')[0] == HOST, 'HOST_OR_IDENTITY')
    rawzip, files, tools, request = validate_payload()
    for path in (Path('/var'), Path('/var/lib'), BASE, BASE / 'state', BASE / 'logs'):
        info = os.lstat(str(path))
        require(stat.S_ISDIR(info.st_mode) and not stat.S_ISLNK(info.st_mode), 'PARENT_NOT_REAL_DIRECTORY:' + str(path))
    parent_before = os.lstat(str(BASE))
    require((parent_before.st_uid, parent_before.st_gid, stat.S_IMODE(parent_before.st_mode)) == (0, 0, 0o700), 'PARENT_IDENTITY_CHANGED')
    # This is a first-install command. Existing partial/committed state is NEVER reset.
    require(not any(os.path.lexists(str(p)) for p in (ROOT, INPUT, LOGS)), 'EXISTING_B1_PATH_RETAIN_AND_RECONCILE')
    lock = os.open(str(BASE / 'state/.formal-cli.lock'), os.O_RDWR | os.O_CREAT | os.O_NOFOLLOW, 0o600)
    try:
        lock_info = os.fstat(lock)
        require(stat.S_ISREG(lock_info.st_mode) and lock_info.st_uid == 0 and stat.S_IMODE(lock_info.st_mode) == 0o600, 'INSTALL_LOCK_IDENTITY')
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        directory(LOGS, 0, 0, 0o700)
        summary = {'scope': 'ISOLATED_TEST_ONLY', 'status': 'NOT_EXECUTED', 'calls': [],
                   'image': IMAGE, 'tool_commit': TOOL_COMMIT, 'zip_sha256': ZIP_SHA,
                   'tar_sha256': TAR_SHA, 'manifest_sha256': MANIFEST_SHA,
                   'request_sha256': REQUEST_SHA, 'request': request, 'production_activated': False,
                   'invoke_id': None, 'source_sha256': sha(Path(__file__).read_bytes()),
                   'retained_paths': [str(ROOT), str(INPUT), str(LOGS)]}
        try:
            write(LOGS / 'owner-script.py', Path(__file__).read_bytes())
            write(LOGS / 'request.json', files['execute-request.json'])
            directory(INPUT, 0, 1002, 0o550)
            write(INPUT / 'source-artifact.zip', rawzip, 0, 1002, 0o440)
            for name, raw in sorted(files.items()):
                write(INPUT / name, raw, 0, 1002, 0o440)
            directory(INPUT / 'tools', 0, 1002, 0o550)
            directory(INPUT / 'tools/production', 0, 1002, 0o550)
            directory(INPUT / 'tools/production/p2_artifacts', 0, 1002, 0o550)
            for name, raw in sorted(tools.items()):
                write(INPUT / 'tools' / name, raw, 0, 1002, 0o440)
            summary['tool_sha256'] = {name: sha(raw) for name, raw in tools.items()}
            directory(ROOT, 1002, 1002, 0o700)
            baseline = None
            for action in ('execute', 'inspect', 'recover'):
                name = 'p2-uk-b1-' + action + '-20261020'
                args = command(action)
                call = {'action': action, 'argv': args, 'started_utc': int(time.time()), 'exit_code': None}
                summary['calls'].append(call)
                with (LOGS / (action + '-stdout.json')).open('xb') as out, (LOGS / (action + '-stderr.log')).open('xb') as err:
                    try:
                        p = subprocess.run(args, input=files['execute-request.json'], stdout=out, stderr=err, timeout=120)
                        call['exit_code'] = p.returncode
                    except subprocess.TimeoutExpired:
                        call['timeout'] = True
                        if (LOGS / (action + '.cid')).is_file():
                            cid = (LOGS / (action + '.cid')).read_text().strip()
                            require(re.fullmatch('[0-9a-f]{64}', cid), 'INVALID_OWN_CONTAINER_ID')
                            stopped = subprocess.run(['/bin/docker', 'stop', '--time=3', cid], stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=15)
                            call['stop_exit'] = stopped.returncode
                        else:
                            call['stop_result'] = 'NO_CREATED_CID_NO_UNKNOWN_CONTAINER_STOP'
                    finally:
                        out.flush(); os.fsync(out.fileno())
                        err.flush(); os.fsync(err.fileno())
                call['ended_utc'] = int(time.time())
                cid = (LOGS / (action + '.cid')).read_text().strip()
                require(re.fullmatch('[0-9a-f]{64}', cid), 'INVALID_OWN_CONTAINER_ID')
                call['container_id'] = cid
                state = container_state(cid)
                call['container'] = state
                write(LOGS / (action + '-container.json'), json.dumps(state, sort_keys=True, indent=2).encode())
                require(state['state']['Running'] is False, 'CONTAINER_STILL_RUNNING_RETAIN_STATE')
                require(state['image'] == IMAGE and state['user'] == '1002:1002'
                        and state['network'] == 'none' and state['readonly'] is True
                        and 'ALL' in state['cap_drop']
                        and any(x.startswith('no-new-privileges') for x in state['security_opt'])
                        and state['memory'] == 536870912 and state['memory_swap'] == 1073741824
                        and state['pids'] == 96 and state['cpu_quota'] == 0 and state['nano_cpus'] == 0,
                        'ACTUAL_CONTAINER_BOUNDARY_MISMATCH')
                mounts = {(x['Source'], x['Destination'], x['RW'], x['Type']) for x in state['mounts']}
                require(mounts == {(str(INPUT), '/input', False, 'bind'),
                                   (str(ROOT), str(ROOT), True, 'bind')}, 'ACTUAL_MOUNT_MISMATCH')
                raw, unused = read_file(LOGS / (action + '-stdout.json'))
                stderr, unused = read_file(LOGS / (action + '-stderr.log'))
                call['stdout'] = raw.decode('utf-8', 'replace')
                call['stderr'] = stderr.decode('utf-8', 'replace')
                call['stdout_sha256'] = sha(raw)
                call['stderr_sha256'] = sha(stderr)
                require(call['exit_code'] == 0, 'CLI_FAILED_RETAIN_STATE:' + action)
                response = json.loads(raw.decode())
                call['response'] = response
                require(response['status'] == 'COMMITTED', 'NOT_COMMITTED:' + action)
                for key in ('schema','scope','installation_id','batch_id','attempt_id'):
                    require(response[key] == request[key], 'RESPONSE_IDENTITY:' + key)
                observed, receipt_raw = installed(request)
                require(response['receipt'] == {k: observed['receipt'][k] for k in ('path','sha256')}, 'RECEIPT_REFERENCE')
                call['observed'] = observed
                if baseline is None:
                    baseline = observed
                    write(LOGS / 'original-commit-receipt.json', receipt_raw)
                else:
                    require(observed == baseline, 'COMMITTED_BYTES_OR_METADATA_CHANGED:' + action)
                write(LOGS / (action + '-result.json'), json.dumps(call, sort_keys=True, indent=2).encode())
            after = os.lstat(str(BASE))
            require((after.st_uid, after.st_gid, stat.S_IMODE(after.st_mode), after.st_ino) ==
                    (0, 0, 0o700, parent_before.st_ino), 'PARENT_CHANGED')
            summary['status'] = 'B1_UK_ISOLATED_ARTIFACT_INSTALL_PASS'
        except Exception as exc:
            summary['status'] = 'FAILED_RETAINED'
            summary['error'] = {'type': type(exc).__name__, 'detail': str(exc)}
        finally:
            summary['ended_utc'] = int(time.time())
            write(LOGS / 'summary.json', json.dumps(summary, sort_keys=True, indent=2).encode())
            print(json.dumps(summary, sort_keys=True, indent=2))
            print('RETAINED_SUMMARY=' + str(LOGS / 'summary.json'))
        return 0 if summary['status'] == 'B1_UK_ISOLATED_ARTIFACT_INSTALL_PASS' else 2
    finally:
        os.close(lock)


if __name__ == '__main__':
    try:
        sys.exit(main())
    except Exception as exc:
        print(json.dumps({'scope': 'ISOLATED_TEST_ONLY', 'status': 'HOLD_RETAIN_STATE',
                          'error': {'type': type(exc).__name__, 'detail': str(exc)},
                          'production_activated': False}, sort_keys=True))
        sys.exit(2)
